FolderCreator = {
	init: async function(app, container, parentId, callback) {
		app = app || session.app;
		container = container || $(".component[name=FolderCreator]");
        var folder = kendo.observable({
            "AppId": app.Id,
            "ParentId": parentId,
            "Name": ""
        });
		kendo.bind(container, folder);

		$("[name=create]", container).on("click", (e) => FolderCreator.createFolder(e, folder, callback));
	},

	createFolder: async function(e, model, callback) {
		e.preventDefault();
		await api.post("DocumentManagement/Folder", model.toJSON(), callback).then((folder) => {
			notification.success("[resource_displayname[added]]");
			callback(folder);
		}).catch((err) => error(err));
	}
}
